import{_ as o,o as t,c as a,ae as s}from"./chunks/framework.sRTLHEzD.js";const p=JSON.parse('{"title":"Move between panes you have used","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/pane_focus_history.md","filePath":"documentation/pane_focus_history.md"}'),r={name:"documentation/pane_focus_history.md"};function n(h,e,i,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="move-between-panes-you-have-used" tabindex="-1">Move between panes you have used <a class="header-anchor" href="#move-between-panes-you-have-used" aria-label="Permalink to &quot;Move between panes you have used&quot;">​</a></h1><p>Use the pane focus history to return to a pane you used earlier or move forward again.</p><h2 id="go-back-or-forward" tabindex="-1">Go back or forward <a class="header-anchor" href="#go-back-or-forward" aria-label="Permalink to &quot;Go back or forward&quot;">​</a></h2><p>The pane focus history is a list of panes that had keyboard focus. The <strong>Back button</strong> and <strong>Forward button</strong> are at the top of the window, immediately left of the search button.</p><ol><li>Click a pane, tab, or workspace to focus the pane you want to use.</li><li>To return to the pane you focused before, click the <strong>Back button</strong>. Heidrun Code selects that pane&#39;s workspace and tab.</li><li>To return to a pane you left by going back, click the <strong>Forward button</strong>.</li></ol><p>The history records a pane after it keeps focus for 500 milliseconds. A quick pass through a pane is not recorded. A button is disabled when there is no earlier or later pane in that direction.</p><h2 id="choose-a-pane-from-the-history-list" tabindex="-1">Choose a pane from the history list <a class="header-anchor" href="#choose-a-pane-from-the-history-list" aria-label="Permalink to &quot;Choose a pane from the history list&quot;">​</a></h2><ol><li>Press and hold the <strong>Back button</strong> or <strong>Forward button</strong> for at least 500 milliseconds.</li><li>In the list that opens, choose the pane entry. The list shows the pane name, workspace, and tab, with the nearest entries first.</li></ol><p>Heidrun Code focuses the chosen pane and closes the list. The list also closes when you click outside it or press Escape. The click that releases the long press does not move through the history.</p><h2 id="use-keyboard-shortcuts" tabindex="-1">Use keyboard shortcuts <a class="header-anchor" href="#use-keyboard-shortcuts" aria-label="Permalink to &quot;Use keyboard shortcuts&quot;">​</a></h2><ol><li>Press <strong>⌘[</strong> to go back through the pane focus history.</li><li>Press <strong>⌘]</strong> to go forward through the pane focus history.</li></ol><p>These shortcuts also work in Zen Mode, where the top bar is hidden. The file explorer keeps these shortcuts for its editor.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun_code/documentation/shortcuts.html">Keyboard shortcuts</a>: look up other keyboard shortcuts.</li><li><a href="/heidrun_code/features/panes.html">The panes</a>: learn how panes work in Heidrun Code.</li></ul>',14)])])}const f=o(r,[["render",n]]);export{p as __pageData,f as default};
